CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,description TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'STUDENT' CHECK(role IN('STUDENT','LIBRARIAN','ADMIN')),student_id VARCHAR(50) UNIQUE,department VARCHAR(100),year INT,phone VARCHAR(30),active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS books(id SERIAL PRIMARY KEY,isbn VARCHAR(40) UNIQUE,title VARCHAR(255) NOT NULL,author VARCHAR(180) NOT NULL,publisher VARCHAR(180),category_id INT REFERENCES categories(id) ON DELETE SET NULL,description TEXT,total_copies INT NOT NULL DEFAULT 1 CHECK(total_copies>=0),available_copies INT NOT NULL DEFAULT 1 CHECK(available_copies>=0),shelf_location VARCHAR(80),publication_year INT,status VARCHAR(20) DEFAULT 'AVAILABLE' CHECK(status IN('AVAILABLE','UNAVAILABLE','INACTIVE')),created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW(),CHECK(available_copies<=total_copies));
ALTER TABLE books ADD COLUMN IF NOT EXISTS catalogue_id VARCHAR(40);
UPDATE books SET catalogue_id='LIB-'||lpad(id::text,8,'0') WHERE catalogue_id IS NULL;
ALTER TABLE books ALTER COLUMN catalogue_id SET DEFAULT ('LIB-'||upper(replace(gen_random_uuid()::text,'-','')));
ALTER TABLE books ALTER COLUMN catalogue_id SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_books_catalogue_id ON books(catalogue_id);
CREATE TABLE IF NOT EXISTS book_issues(id SERIAL PRIMARY KEY,book_id INT NOT NULL REFERENCES books(id),student_id INT NOT NULL REFERENCES users(id),issued_by INT REFERENCES users(id),issue_date DATE DEFAULT CURRENT_DATE,due_date DATE NOT NULL,return_date DATE,status VARCHAR(30) DEFAULT 'ISSUED' CHECK(status IN('ISSUED','RETURNED','OVERDUE','RENEWAL_REQUESTED')),fine_amount NUMERIC(10,2) DEFAULT 0,renewal_count INT DEFAULT 0,created_at TIMESTAMP DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS uq_active_issue ON book_issues(student_id,book_id) WHERE status IN('ISSUED','OVERDUE','RENEWAL_REQUESTED');
CREATE TABLE IF NOT EXISTS waitlist(id SERIAL PRIMARY KEY,book_id INT REFERENCES books(id) ON DELETE CASCADE,student_id INT REFERENCES users(id) ON DELETE CASCADE,position INT NOT NULL,status VARCHAR(20) DEFAULT 'WAITING',created_at TIMESTAMP DEFAULT NOW(),UNIQUE(book_id,student_id));
CREATE TABLE IF NOT EXISTS fines(id SERIAL PRIMARY KEY,issue_id INT REFERENCES book_issues(id) ON DELETE CASCADE,student_id INT REFERENCES users(id) ON DELETE CASCADE,amount NUMERIC(10,2) CHECK(amount>=0),reason VARCHAR(255),status VARCHAR(20) DEFAULT 'UNPAID',created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(200),message TEXT,type VARCHAR(40) DEFAULT 'INFO',is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS feedback(id SERIAL PRIMARY KEY,student_id INT REFERENCES users(id),book_id INT REFERENCES books(id),rating INT CHECK(rating BETWEEN 1 AND 5),comment TEXT,ai_sentiment VARCHAR(50),ai_summary TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS automation_logs(id SERIAL PRIMARY KEY,workflow_name VARCHAR(150),execution_id VARCHAR(150),status VARCHAR(30),message TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS book_imports(id SERIAL PRIMARY KEY,actor_id INT REFERENCES users(id) ON DELETE SET NULL,file_name VARCHAR(255) NOT NULL,total_rows INT NOT NULL,imported_rows INT NOT NULL DEFAULT 0,updated_rows INT NOT NULL DEFAULT 0,duplicate_rows INT NOT NULL DEFAULT 0,skipped_rows INT NOT NULL DEFAULT 0,error_rows INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs(id SERIAL PRIMARY KEY,actor_id INT REFERENCES users(id) ON DELETE SET NULL,event_type VARCHAR(100) NOT NULL,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_books_title ON books(title); CREATE INDEX IF NOT EXISTS idx_books_author ON books(author); CREATE INDEX IF NOT EXISTS idx_issue_student ON book_issues(student_id); CREATE INDEX IF NOT EXISTS idx_issue_due ON book_issues(due_date); CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_book_imports_actor_created ON book_imports(actor_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_actor_created ON audit_logs(actor_id,created_at DESC);
